  9	namespace UI\Icons;
 10	
 11	use AppUtils\FileHelper\JSONFile;
 12	
 13	/**
 14	 * Singleton registry of all available icons — both framework standard icons
 15	 * and application custom icons. On first access the collection loads and
 16	 * merges the two JSON sources, normalises IDs (hyphens/spaces → underscores),
 17	 * and sorts the result alphabetically by icon ID.
 18	 *
 19	 * Custom icons with the same ID as a standard icon replace the standard entry,
 20	 * allowing applications to override framework icons.
 21	 *
 22	 * @package UI
 23	 * @subpackage Icons
 24	 * @see IconInfo
 25	 */
 26	class IconCollection
 27	{
 28	    private static ?IconCollection $instance = null;
 29	
 30	    /**
 31	     * @var array<string,IconInfo>
 32	     */
 33	    private array $icons = array();
 34	
 35	    private function __construct()
 36	    {
 37	        $this->loadIcons();
 38	    }
 39	
 40	    public static function getInstance() : self
 41	    {
 42	        if(self::$instance === null)
 43	        {
 44	            self::$instance = new self();
 45	        }
 46	
 47	        return self::$instance;
 48	    }
 49	
 50	    /**
 51	     * Resets the singleton instance to null.
 52	     *
 53	     * @internal For use in tests only — allows each test to start with a
 54	     *           fresh collection instance and prevents state leaking between
 55	     *           test cases.
 56	     * @return void
 57	     */
 58	    public static function resetInstance() : void
 59	    {
 60	        self::$instance = null;
 61	    }
 62	
 63	    /**
 64	     * Returns all available icons sorted alphabetically by ID.
 65	     *
 66	     * @return IconInfo[]
 67	     */
 68	    public function getAll() : array
 69	    {
 70	        return array_values($this->icons);
 71	    }
 72	
 73	    /**
 74	     * Returns only the framework standard icons, sorted alphabetically by ID.
 75	     *
 76	     * @return IconInfo[]
 77	     */
 78	    public function getStandardIcons() : array
 79	    {
 80	        $result = array();
 81	
 82	        foreach($this->icons as $icon)
 83	        {
 84	            if($icon->isStandard())
 85	            {
 86	                $result[] = $icon;
 87	            }
 88	        }
 89	
 90	        return $result;
 91	    }
